INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('49187d39-6121-44b9-8477-f19e16fac16b', 'Era of Vestiges', 3, 'ERA', NULL, 'The oldest era of the temporal world, predating the creation of matter. In a yet-nonexistent universe, vestiges of a previous world drift adrift, ready for a new story.', '2026-06-23 18:54:04.13818+00', '2026-06-23 18:54:04.13818+00', 'en', '49187d39-6121-44b9-8477-f19e16fac16b');
INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('1a3a86db-9f36-4c9b-9509-1346576efdaa', 'Crash of the Prima Airship into the Sun', 4, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:04.151342+00', '2026-06-23 18:54:04.151342+00', 'en', '1a3a86db-9f36-4c9b-9509-1346576efdaa');
INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('47eb040e-b0d3-492a-8817-525a91705240', 'Era of Glimpses', 5, 'ERA', NULL, 'Beneath a mountain, the first concepts emerge.', '2026-06-23 18:54:04.164302+00', '2026-06-23 18:54:04.164302+00', 'en', '47eb040e-b0d3-492a-8817-525a91705240');
INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('b8b2d895-402d-4a88-a689-6b418ed0384c', 'Dot''s Escape', 6, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:04.368255+00', '2026-06-23 18:54:04.368255+00', 'en', 'b8b2d895-402d-4a88-a689-6b418ed0384c');
INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('733fa7c5-700d-418e-bcdd-64afe020bf3f', 'Era of the Unpronounceable', 7, 'ERA', NULL, 'Concepts begin to take shape; different peoples spread beneath the earth. An era defined by the conflict between individuation and union.', '2026-06-23 18:54:04.38277+00', '2026-06-23 18:54:04.38277+00', 'en', '733fa7c5-700d-418e-bcdd-64afe020bf3f');
INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('2c26e128-ea8d-4910-9d2d-9de56aca40cf', 'Victory of the People of Symbols', 8, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:04.399434+00', '2026-06-23 18:54:04.399434+00', 'en', '2c26e128-ea8d-4910-9d2d-9de56aca40cf');
INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('af4bc3ba-5848-4c59-bceb-576f5528f939', 'Era of Symbols', 9, 'ERA', NULL, 'An empire of unpronounceable concepts emerges, refusing to accept divine authority.', '2026-06-23 18:54:04.418364+00', '2026-06-23 18:54:04.418364+00', 'en', 'af4bc3ba-5848-4c59-bceb-576f5528f939');
INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('98706f60-12d5-40a0-8291-ecfa3dfb9d5c', 'Death of Jung Blackheart, Chief Resister', 10, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:04.450108+00', '2026-06-23 18:54:04.450108+00', 'en', '98706f60-12d5-40a0-8291-ecfa3dfb9d5c');
INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('ec1a7fa1-7316-47df-9689-f7a65359cc87', 'Era of Forms', 11, 'ERA', NULL, 'Concepts cross the Black Lake and begin to take shape before the light of truth.', '2026-06-23 18:54:04.462402+00', '2026-06-23 18:54:04.462402+00', 'en', 'ec1a7fa1-7316-47df-9689-f7a65359cc87');
INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('1cabbeb8-bcc3-44e1-8367-c193a38e619b', 'Discovery of Singisdonia', 12, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:04.47631+00', '2026-06-23 18:54:04.47631+00', 'en', '1cabbeb8-bcc3-44e1-8367-c193a38e619b');
INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('7723f15f-18cc-43f9-81e4-72ee47f5cee3', 'Era of Singisdonia', 13, 'ERA', NULL, 'A time of light and evolution in the sacred city.', '2026-06-23 18:54:04.489599+00', '2026-06-23 18:54:04.489599+00', 'en', '7723f15f-18cc-43f9-81e4-72ee47f5cee3');
INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('7315666c-2840-4635-980c-ec4d138f9c82', 'Attack of the Red King', 14, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:04.500854+00', '2026-06-23 18:54:04.500854+00', 'en', '7315666c-2840-4635-980c-ec4d138f9c82');
INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('f583b008-820b-4a1a-8f41-35f90725042e', 'Era of Monads', 15, 'ERA', NULL, 'Concepts now migrate in search of another home, learning to grow on their own.', '2026-06-23 18:54:04.515353+00', '2026-06-23 18:54:04.515353+00', 'en', 'f583b008-820b-4a1a-8f41-35f90725042e');
INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('1ede2bc9-af3b-4b72-83ce-f041a3d3a78c', 'Death of Teo', 16, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:04.52704+00', '2026-06-23 18:54:04.52704+00', 'en', '1ede2bc9-af3b-4b72-83ce-f041a3d3a78c');
INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('8c57f579-e96a-41e4-821e-ee325c91384a', 'Era of the Platiad', 17, 'ERA', NULL, 'Concepts migrate into the Black Lake, and an era of intellect prevails.', '2026-06-23 18:54:04.731718+00', '2026-06-23 18:54:04.731718+00', 'en', '8c57f579-e96a-41e4-821e-ee325c91384a');
INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('d4509309-000e-4aaa-8640-d0d19425b846', 'Creation of the Material World', 18, 'POINT', 'MAJOR', NULL, '2026-06-23 18:54:04.746165+00', '2026-06-23 18:54:04.746165+00', 'en', 'd4509309-000e-4aaa-8640-d0d19425b846');
INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('2f0b14b1-2db2-4b78-a15b-d91b9344c26b', 'Era of Matter', 19, 'ERA', NULL, 'First semi-material beings shaped by the first particles.', '2026-06-23 18:54:04.75899+00', '2026-06-23 18:54:04.75899+00', 'en', '2f0b14b1-2db2-4b78-a15b-d91b9344c26b');
