INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('d89ab35d-6b25-431e-95c4-7d0ae419d84f', 'Era of Heroes', 35, 'ERA', NULL, 'Great civilisations arise, and their heroes alongside them.', '2026-06-23 18:54:05.155195+00', '2026-06-23 18:54:05.155195+00', 'en', 'd89ab35d-6b25-431e-95c4-7d0ae419d84f');
