INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('2eff7424-b158-43f9-a8a7-8992b3042295', 'Era of Law', 43, 'ERA', NULL, 'The study of military armament takes off, and a new wave of conquest begins among the most advanced nations.', '2026-06-23 18:54:05.651498+00', '2026-06-23 18:54:05.651498+00', 'en', '2eff7424-b158-43f9-a8a7-8992b3042295');
