INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('13bd8972-a1c3-4e37-82b1-6f05e4040566', 'Era of Encounters', 47, 'ERA', NULL, 'Several civilisations are destroyed; others advance to the level of interplanetary travel.', '2026-06-23 18:54:05.708094+00', '2026-06-23 18:54:05.708094+00', 'en', '13bd8972-a1c3-4e37-82b1-6f05e4040566');
INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('83d1b21c-8399-43e3-99dc-0068d116c9a8', 'Intergalactic Catastrophe', 48, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:05.719254+00', '2026-06-23 18:54:05.719254+00', 'en', '83d1b21c-8399-43e3-99dc-0068d116c9a8');
INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('ff3d5bed-6438-4fdb-8919-0a41250ff71e', 'Era of Dust', 49, 'ERA', NULL, 'The world lives in a post-apocalyptic scenario; lack of resources brings society ever closer to its end.', '2026-06-23 18:54:05.732025+00', '2026-06-23 18:54:05.732025+00', 'en', 'ff3d5bed-6438-4fdb-8919-0a41250ff71e');
