INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('681bb88e-e884-4668-83e6-db068f18b5df', 'Morte de Jung Coração-Negro, Chefe da Resistência', 10, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:04.450108+00', '2026-06-23 18:54:04.450108+00', 'pt', '98706f60-12d5-40a0-8291-ecfa3dfb9d5c');
INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('5da9b2fc-5678-4178-8292-c5d606deda84', 'Era das Formas', 11, 'ERA', NULL, 'Os conceitos atravessam o Lago Negro e começam a tomar forma diante da luz da verdade.', '2026-06-23 18:54:04.462402+00', '2026-06-23 18:54:04.462402+00', 'pt', 'ec1a7fa1-7316-47df-9689-f7a65359cc87');
INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('cadf2ecf-77d4-49ef-96cd-e0f0a57c96fb', 'Descoberta de Singisdônia', 12, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:04.47631+00', '2026-06-23 18:54:04.47631+00', 'pt', '1cabbeb8-bcc3-44e1-8367-c193a38e619b');
