INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('1fac2c4b-0967-4699-945f-f05d9c769252', 'Era da Magia', 37, 'ERA', NULL, 'A magia é usada de forma cada vez mais imprudente. A segregação entre os povos cresce. As monarquias começam a cair.', '2026-06-23 18:54:05.180959+00', '2026-06-23 18:54:05.180959+00', 'pt', 'e54477b9-c9f8-4c51-9bf6-41d3802daf3b');
INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('ebba5ed0-9a11-4fbf-95d5-2e741ffe6687', 'Reabertura das Fendas Cósmicas', 38, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:05.19475+00', '2026-06-23 18:54:05.19475+00', 'pt', 'a315a026-5488-4823-a1e6-b6c1c20238d8');
INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('95e57557-a3e0-4bec-a998-c11c10f7c09e', 'Era do Iluminismo', 39, 'ERA', NULL, 'O mundo começa a perceber os perigos da magia. Surgem movimentos inquisitoriais e pesquisas tecnológicas.', '2026-06-23 18:54:05.206857+00', '2026-06-23 18:54:05.206857+00', 'pt', 'b33d7a47-cf46-4aa1-a6c5-b7527ec0de37');
INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('abeafef4-11a3-4238-bef1-5a2eb1fde2fb', 'Fim da Magia', 40, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:05.417734+00', '2026-06-23 18:54:05.417734+00', 'pt', 'd8d07906-b053-4eaf-9cad-ebc71a3d2fc3');
INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('648c844e-8c7e-4724-8a34-fe4b7c1083ea', 'Era dos Artefatos', 41, 'ERA', NULL, 'Artefatos antigos ainda guardam poder mágico e são buscados por todos como fontes de força.', '2026-06-23 18:54:05.622571+00', '2026-06-23 18:54:05.622571+00', 'pt', 'ebd3f220-f0bb-4073-a6f9-ed790e245679');
INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('d14c6617-78fd-4641-a074-80e20815e569', 'Estabelecimento da Nova Ordem Tecnológica', 42, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:05.6372+00', '2026-06-23 18:54:05.6372+00', 'pt', 'd96d7190-b5cd-415b-95c5-fe42b28bf2b7');
INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('747bfdd2-8ec9-4416-976d-4051bf90276b', 'Era da Lei', 43, 'ERA', NULL, 'O estudo do armamento militar decola, e uma nova onda de conquista começa entre as nações mais avançadas.', '2026-06-23 18:54:05.651498+00', '2026-06-23 18:54:05.651498+00', 'pt', '2eff7424-b158-43f9-a8a7-8992b3042295');
INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('13a19810-290b-44b5-a8e2-6b8c588696e3', 'Surgimento da Robótica, Eletrônica e Programação', 44, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:05.665055+00', '2026-06-23 18:54:05.665055+00', 'pt', '34e4d7e0-d540-4079-923a-9f88803e2488');
INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('5ae11af6-d394-48f6-bb05-0e68fd241084', 'Era da Tecnologia', 45, 'ERA', NULL, 'O mundo se torna completamente dominado pela tecnologia.', '2026-06-23 18:54:05.683915+00', '2026-06-23 18:54:05.683915+00', 'pt', 'fe965866-a03a-4287-b4a8-b6d9eac9acb8');
INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('02bd0af8-0338-4a2b-a6c3-1fffffa451aa', 'Rebelião das Máquinas', 46, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:05.695639+00', '2026-06-23 18:54:05.695639+00', 'pt', '34ca791f-6c98-4262-87d7-4b8abf13f328');
INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('7aba3c3a-c576-4efa-8684-c068177e0f3e', 'Era dos Encontros', 47, 'ERA', NULL, 'Diversas civilizações são destruídas; outras avançam ao nível de viagens interplanetárias.', '2026-06-23 18:54:05.708094+00', '2026-06-23 18:54:05.708094+00', 'pt', '13bd8972-a1c3-4e37-82b1-6f05e4040566');
INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('f39e3ec0-09d1-41ae-bef5-ff27b5ef36ba', 'Catástrofe Intergaláctica', 48, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:05.719254+00', '2026-06-23 18:54:05.719254+00', 'pt', '83d1b21c-8399-43e3-99dc-0068d116c9a8');
INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('3fdc7efb-17d8-4575-8106-146953843f09', 'Era da Poeira', 49, 'ERA', NULL, 'O mundo vive um cenário pós-apocalíptico; a falta de recursos aproxima cada vez mais a sociedade de seu fim.', '2026-06-23 18:54:05.732025+00', '2026-06-23 18:54:05.732025+00', 'pt', 'ff3d5bed-6438-4fdb-8919-0a41250ff71e');
INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('93d9c0e6-e254-44ea-85ae-b703bcce06bd', 'Começa a Guerra dos Hexágonos', 50, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:05.742603+00', '2026-06-23 18:54:05.742603+00', 'pt', '659fdc07-604a-46b1-aa0e-133d7e54e5b8');
INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('cdaf8525-4ad7-4952-b93e-5fef4066aa0c', 'Era da Morte', 51, 'ERA', NULL, 'O mundo é assolado por conflitos constantes e marcha rumo ao seu fim.', '2026-06-23 18:54:05.914423+00', '2026-06-23 18:54:05.914423+00', 'pt', 'fd791fd4-6951-4fa8-957e-5979bff9427f');
INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('b28c235a-0c6a-4b3d-9cf8-518eeec63559', 'Fim dos Mortais', 52, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:05.928631+00', '2026-06-23 18:54:05.928631+00', 'pt', 'f4f343d5-9208-45f9-b7d4-3debe69443da');
INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('36d5e2a5-be00-456b-bf11-113c0b737904', 'Era Primordial', 1, 'ERA', NULL, 'A era anterior à existência do mundo material — um tempo de pura essência, forças divinas e o alicerce sobre o qual toda a existência viria a ser construída. Nenhum mundo navegável existe aqui; apenas o infinito.', '2026-06-23 18:54:04.047617+00', '2026-06-24 02:31:11.341815+00', 'pt', '48ed4b49-b7b5-4d4b-9715-00dcaa819209');
